def chunks(items, size):
    if size <= 0: raise ValueError('size')
    return [items[i:i+size] for i in range(0, len(items), size)]

alternate:
def chunks(items, size):
    if size < 1: raise ValueError()
    out = []
    for i in range(0, len(items), size): out.append(list(items[i:i+size]))
    return out
